// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

test('handleBrickCollision: top face hit flips vy', () => {
  const ball = { x: 100, y: 80, r: 10, vx: 0, vy: 100 };
  const brick = { x: 90, y: 90, w: 20, h: 20 };
  // Ball is at 80, radius 10 -> bottom is at 90. Hits top of brick.
  handleBrickCollision(ball, brick);
  assert.equal(ball.vy, -100, 'vy should be flipped');
  assert.equal(ball.y, 80, 'ball should be pushed out to top of brick'); 
  // Wait, if it's pushed out, y should be brick.y - ball.r = 90 - 10 = 80.
});

test('handleBrickCollision: side face hit flips vx', () => {
  const ball = { x: 80, y: 100, r: 10, vx: 100, vy: 0 };
  const brick = { x: 90, y: 90, w: 20, h: 20 };
  // Ball is at 80, radius 10 -> right edge is at 90. Hits left side of brick.
  handleBrickCollision(ball, brick);
  assert.equal(ball.vx, -100, 'vx should be flipped');
});

test('handleBrickCollision: corner hit flips both', () => {
  const ball = { x: 85, y: 85, r: 10, vx: 100, vy: 100 };
  const brick = { x: 90, y: 90, w: 20, h: 20 };
  // Overlap on both axes.
  handleBrickCollision(ball, brick);
  assert.equal(ball.vx, -100);
  assert.equal(ball.vy, -100);
});

test('handleBrickCollision: push-out prevents stickiness', () => {
  const ball = { x: 100, y: 95, r: 10, vx: 0, vy: 100 };
  const brick = { x: 90, y: 90, w: 20, h: 20 };
  // Ball is deep inside the brick.
  handleBrickCollision(ball, brick);
  assert.ok(!collides(ball, brick), 'ball should be pushed out of the brick');
});

