// Resolves a collision between the ball and a brick.
// Returns true if a collision occurred and the ball was deflected.
export function handleBrickCollision(ball, brick, force = false) {
  if (!force && !collides(ball, brick)) return false;

  if (force) {
    const originalVx = ball.vx;
    const originalVy = ball.vy;
    if (Math.abs(originalVx) > Math.abs(originalVy)) {
      ball.vx = originalVx > 0 ? -Math.abs(originalVx) : Math.abs(originalVx);
      ball.x = originalVx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
    } else {
      ball.vy = originalVy > 0 ? -Math.abs(originalVy) : Math.abs(originalVy);
      ball.y = originalVy > 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
    return true;
  }

  const overlapX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);

  if (overlapX < overlapY) {
    ball.vx = ball.x < brick.x + brick.w / 2 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (overlapY < overlapX) {
    ball.vy = ball.y < brick.y + brick.h / 2 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    ball.vx = ball.x < brick.x + brick.w / 2 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = ball.y < brick.y + brick.h / 2 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
  return true;
}

